def solve_math_problem(n: int):
    # Precompute perfect squares up to 2*n
    max_sum = 2 * n
    squares = {i * i for i in range(1, int(max_sum ** 0.5) + 1)}

    # Build adjacency list
    graph = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if i + j in squares:
                graph[i].append(j)
                graph[j].append(i)

    # Depth-first search to find a Hamiltonian path
    def backtrack(path, used):
        if len(path) == n:
            return path[0] + path[-1]
        last = path[-1]
        for neighbor in graph[last]:
            if neighbor not in used:
                used.add(neighbor)
                path.append(neighbor)
                result = backtrack(path, used)
                if result is not None:
                    return result
                path.pop()
                used.remove(neighbor)
        return None

    # Try every vertex as starting point
    for start in range(1, n + 1):
        used = {start}
        path = [start]
        result = backtrack(path, used)
        if result is not None:
            return result
    return None
